//! The shape of the Public Suffix List tables in [`super::data`]
//! (generated by `cargo xtask tables`).

#[allow(unused_imports)]
use vstd::prelude::*;

verus! {

/// A rule of the list: its text is `PSL_CHARS[start .. start + len]`, and
/// `exception` is whether the line started with `!`.
#[derive(Clone, Copy)]
pub struct RuleRow {
    /// Where the rule's text starts in `PSL_CHARS`.
    pub start: u32,
    /// The text's length.
    pub len: u32,
    /// Whether this is an exception rule.
    pub exception: bool,
}

} // verus!
